def reduce_current(path,raw):
 if path not in SOURCE_INPUTS:return raw
 if type(raw)is not bytes or hashlib.sha256(raw).hexdigest()!=SOURCE_INPUTS[path]:raise ValueError('unreviewed Assessment source')
 for added,removed in EDITS[path]:
  if raw.count(added)!=1:raise ValueError('Assessment inverse shape changed')
  raw=raw.replace(added,removed,1)
 if hashlib.sha256(raw).hexdigest()!=BASE_PINS[path]:raise ValueError('Assessment changed other native bytes')
 return raw
